package io.github.chronicle.core.areas;
import java.util.LinkedHashMap;import java.util.Map;import java.util.UUID;
public record AreaOperationJournal(long revision,Map<UUID,AreaOperation> operations){public static final int MAX_OPERATIONS=4096;public AreaOperationJournal{if(revision<0)throw new IllegalArgumentException("journal revision must be non-negative");if(operations==null||operations.size()>MAX_OPERATIONS)throw new IllegalArgumentException("too many operations");LinkedHashMap<UUID,AreaOperation>x=new LinkedHashMap<>();operations.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(e->{if(e.getKey()==null||e.getValue()==null||!e.getKey().equals(e.getValue().operationId()))throw new IllegalArgumentException("operation journal entry is invalid");x.put(e.getKey(),e.getValue());});operations=java.util.Collections.unmodifiableMap(x);}public static AreaOperationJournal empty(){return new AreaOperationJournal(0,Map.of());}}
